import { z } from "zod";
import {
  zBatchDeleteResponsesRequest,
  zBatchDeleteResponsesV3Query,
  zCreateResponseRequest,
  zGetResponseV3Path,
  zPatchResponseRequest,
  zResponseDataMapInput,
  zResponseEmbeddedDataInput,
  zResponseTtcMap,
  zValidateResponseCreateRequest,
  zValidateResponsePatchRequest,
} from "@formbricks/api-v3-schemas";
import { declareReference } from "./reference-manifest";

/**
 * The request schemas of the v3 response routes.
 *
 * The shapes are generated from the contract (`@formbricks/api-v3-schemas`); this module adds what a
 * generated schema cannot carry, and nothing else:
 *
 * - the constraints the generator cannot express — `uniqueItems`, `minProperties`/`maxProperties`
 *   and the `if/then` value caps. Each one is pinned in the package's `EXPECTED_UNENFORCED`, and
 *   `write-schemas.test.ts` rejects a counterexample for every pin, so a constraint published on the
 *   contract cannot go unenforced here.
 * - the messages a caller reads in `invalid_params[].reason`.
 * - strictness for parameter objects, which the generator emits stripping because OpenAPI has no way to
 *   close a parameter list.
 * - the reference declarations of ENG-2861, which must sit on the exact instances the bodies expose.
 *
 * Compose first, refine last: Zod 4 refuses `.extend` over a key once a schema has refinements, and a
 * `.refine` clones its schema — so each declaration below targets the instance that ends up in the
 * final shape.
 */

/** `uniqueItems`, as a refinement. Shared with MCP tools that call the operations directly. */
export const hasUniqueItems = (values: readonly unknown[]): boolean => new Set(values).size === values.length;
export const RESPONSE_IDS_UNIQUE_MESSAGE = "Response ids must be unique";

/**
 * The response id is a path parameter, so it is validated here rather than trusted: an unparseable id
 * must answer 400 before any query runs, not 500 from Prisma (ENG-483 is that bug on the v1 route).
 * `GET`, `PATCH` and `DELETE` share the one `ResponseIdPath` parameter, so any of their path schemas
 * serves.
 */
export const ZV3ResponseIdParams = z.strictObject(zGetResponseV3Path.shape);
export type TV3ResponseIdParams = z.infer<typeof ZV3ResponseIdParams>;

/**
 * `POST /api/v3/responses/batch-delete`.
 *
 * The cap and the uniqueness rule are the contract's, and both are enforced here rather than left to
 * the service: an oversized batch must answer 400 before it reaches a `deleteMany`, and duplicates
 * would make `deleted` unreconcilable against `ids.length` for no benefit to the caller. The rule sits
 * on the array, not the body, so it still reports when another field of the body is also wrong.
 */
export const ZV3BatchDeleteResponsesQuery = z.strictObject(zBatchDeleteResponsesV3Query.shape);
export type TV3BatchDeleteResponsesQuery = z.infer<typeof ZV3BatchDeleteResponsesQuery>;

export const ZV3BatchDeleteResponsesBody = zBatchDeleteResponsesRequest.extend({
  ids: zBatchDeleteResponsesRequest.shape.ids.refine(hasUniqueItems, {
    message: RESPONSE_IDS_UNIQUE_MESSAGE,
  }),
});
export type TV3BatchDeleteResponsesBody = z.infer<typeof ZV3BatchDeleteResponsesBody>;

/**
 * Cardinality caps on a stored answer, per the ENG-1652 input policy — the same reason `tags` and the
 * batch-delete body are capped.
 *
 * Both are far past any real survey: a multi-select answer holds at most one entry per choice, and a
 * response holds at most one entry per element. Without them a single request inside the 2 MB body
 * limit can store an array of tens of thousands of entries, and every later reader pays for it per
 * entry — the serializer's per-answer mapping, export columns, and the positional probe the "Other"
 * response filter emits (ENG-3161), whose window is sized from the survey's choice count rather than
 * from the stored array.
 *
 * v3-only, and additive: the same unbounded shape reaches `ZResponseData` through the v1 and v2 write
 * paths, where capping it would reject payloads that work today.
 */
export const MAX_RESPONSE_DATA_VALUES = 1_000;
export const MAX_RESPONSE_DATA_KEYS = 500;

/**
 * `ResponseDataMapInput`: the stored answer map with the write-side bounds.
 *
 * The contract caps each value with `if/then` — an array at most 1000 items, a matrix at most 1000
 * rows — and the map with `maxProperties`. The value caps refine the generated value union and the
 * key cap refines the map, which reports issues exactly as the per-value `.max()` schema did: a value
 * over its cap and a map over 500 keys are both reported, while a value of the wrong shape fails the
 * map's parse and Zod then skips the key cap. The array cap raises Zod's own `too_big` issue, so its
 * `reason` reads the way a `.max()` would.
 */
const ZV3ResponseDataValue = zResponseDataMapInput.valueType.superRefine((value, ctx) => {
  if (Array.isArray(value)) {
    if (value.length > MAX_RESPONSE_DATA_VALUES) {
      ctx.addIssue({
        code: "too_big",
        origin: "array",
        maximum: MAX_RESPONSE_DATA_VALUES,
        inclusive: true,
        input: value,
      });
    }
  } else if (typeof value === "object" && Object.keys(value).length > MAX_RESPONSE_DATA_VALUES) {
    ctx.addIssue({
      code: "custom",
      input: value,
      message: `A matrix answer may hold at most ${MAX_RESPONSE_DATA_VALUES} rows`,
    });
  }
});

const ZV3ResponseDataInput = z
  .record(zResponseDataMapInput.keyType, ZV3ResponseDataValue)
  .refine((entries) => Object.keys(entries).length <= MAX_RESPONSE_DATA_KEYS, {
    message: `A response may answer at most ${MAX_RESPONSE_DATA_KEYS} fields`,
  });

/**
 * The same key cap `data` carries, for the other two element-keyed maps on this body.
 *
 * `embeddedData` needs it for a second reason beyond storage: every name that matches no declared
 * field becomes its own `invalid_params` entry, and the entry repeats the name in both `name` and
 * `reason`. Uncapped, a 2 MB body of distinct short names answers with a 422 several times its own
 * size — the request is rejected, and the rejection is the expensive part. Only Hub-relayed
 * `invalid_params` are bounded (`hub-errors.ts`); locally generated ones are not.
 */
const withKeyCap = <T extends z.ZodType<Record<string, unknown>>>(schema: T, what: string) =>
  schema.refine((entries) => Object.keys(entries).length <= MAX_RESPONSE_DATA_KEYS, {
    message: `A response may carry at most ${MAX_RESPONSE_DATA_KEYS} ${what}`,
  });

/** Embedded Data accepts scalars only, plus `null` to clear a field — per `ResponseEmbeddedDataInput`. */
const ZV3EmbeddedDataInput = withKeyCap(zResponseEmbeddedDataInput, "Embedded Data fields");

/**
 * Per-element timing, in milliseconds. Values are not bounded on purpose — the contract clamps rather
 * than rejects, because noisy client telemetry should never cost a caller their response. The clamp
 * lives in the service.
 */
const ZV3TtcInput = withKeyCap(zResponseTtcMap, "timing entries");

const createShape = zCreateResponseRequest.shape;
const patchShape = zPatchResponseRequest.shape;

/**
 * Bounded like the batch-delete body. Without the cap one 2 MB request becomes a `WHERE id IN (…)` of
 * tens of thousands of ids plus that many join-row inserts, all inside the write transaction. Unique on
 * create only, as the contract has it: a patch applies its tags as a set, and the service deduplicates
 * them before writing the join rows.
 */
const ZV3CreateTags = createShape.tags
  .unwrap()
  .refine(hasUniqueItems, { message: "Tag ids must be unique" })
  .optional();

/**
 * Every value on a body that names something outside it, declared once (ENG-2861).
 *
 * `reference-manifest.test.ts` reads the bodies, not this list: a new field — including one a spec edit
 * adds through generation — fails there until it is classified here. The point is that the set cannot
 * grow quietly: the twelve response BOLA fixes were each a field nobody knew was a reference.
 */
const fk = (resolvedAgainst: string) => ({ kind: "fk" as const, resolvedAgainst });
const local = (resolvedAgainst: string) => ({ kind: "document-local" as const, resolvedAgainst });
const TAGS_RESOLVED = "Tag filtered by workspaceId in one query, and connected scoped in the write";

declareReference(createShape.surveyId, fk("Survey, resolved and authorized by workspace before the write"));
declareReference(
  createShape.contactId,
  fk("Contact filtered by workspaceId, and connected scoped in the write")
);
declareReference(
  createShape.displayId,
  fk("Display filtered by surveyId and unclaimed, and connected scoped in the write")
);
declareReference(ZV3CreateTags, fk(TAGS_RESOLVED));
declareReference(patchShape.tags, fk(TAGS_RESOLVED));
for (const shape of [createShape, patchShape]) {
  declareReference(shape.endingId, local("the survey's own endings"));
  declareReference(shape.language, local("the survey's own enabled languages"));
}
declareReference(
  ZV3ResponseDataInput,
  local("the survey's element ids; file-upload values additionally carry an embedded-id")
);
declareReference(ZV3EmbeddedDataInput, local("the survey's declared Embedded Data field names"));
declareReference(
  createShape.singleUseId,
  local("unused for this survey — a token, scoped by surveyId rather than owned elsewhere")
);

/**
 * `POST /api/v3/responses`.
 *
 * Three required fields and nothing implied: `surveyId`, `finished` and `data`. Everything the
 * caller may not set is absent from the shape rather than stripped afterwards, so strictness turns an
 * attempt into a 400 naming the key instead of a silent drop — which is the difference between a
 * caller learning that `createdAt` is server-owned and one believing they backdated a response.
 */
export const ZV3CreateResponseBody = zCreateResponseRequest.extend({
  data: ZV3ResponseDataInput,
  embeddedData: ZV3EmbeddedDataInput.optional(),
  ttc: ZV3TtcInput.optional(),
  tags: ZV3CreateTags,
});
export type TV3CreateResponseBody = z.infer<typeof ZV3CreateResponseBody>;

/**
 * `PATCH /api/v3/responses/{responseId}`.
 *
 * Six patchable fields, and at least one of them — an empty body is a 400 rather than a no-op 200,
 * because a caller sending nothing has a bug and a 200 would hide it.
 */
export const ZV3PatchResponseBody = zPatchResponseRequest
  .extend({
    data: ZV3ResponseDataInput.optional(),
    embeddedData: ZV3EmbeddedDataInput.optional(),
  })
  .refine((body) => Object.keys(body).length > 0, { message: "At least one field must be provided" });
export type TV3PatchResponseBody = z.infer<typeof ZV3PatchResponseBody>;

/**
 * `POST /api/v3/responses/validate`.
 *
 * A union discriminated on `operation`, each arm carrying the body the real call would take, like
 * `ZV3SurveyValidationRequestBody`. The envelope is strict and its failures are the endpoint's only
 * 400 — `data` is any value precisely because problems inside it are the point of the endpoint and come
 * back as a `200` with `valid: false`.
 *
 * `data` is required rather than merely `unknown`: Zod treats an `unknown` field as satisfiable by an
 * absent key, so without the check `{ "operation": "create" }` would validate an empty document and
 * report it as a caller error rather than as the malformed envelope it is.
 */
const ZV3ValidationDocument = declareReference(
  z.unknown().refine((value) => value !== undefined, { message: "Required" }),
  local("the nested create or patch body, whose own fields carry their declarations")
);

/**
 * The envelope's own `responseId`. A dry run resolves it exactly as a real patch does —
 * `getResponseWorkspaceId`, then the scoped read — so validate cannot be used to probe whether a
 * response exists in someone else's workspace.
 */
declareReference(
  zValidateResponsePatchRequest.shape.responseId,
  fk("Response, via getResponseWorkspaceId then the workspace-scoped read")
);

export const ZV3ResponseValidationRequestBody = z.discriminatedUnion("operation", [
  zValidateResponseCreateRequest.extend({ operation: z.literal("create"), data: ZV3ValidationDocument }),
  zValidateResponsePatchRequest.extend({ operation: z.literal("patch"), data: ZV3ValidationDocument }),
]);
export type TV3ResponseValidationRequestBody = z.infer<typeof ZV3ResponseValidationRequestBody>;

import { prisma } from "@formbricks/database";
import { logger } from "@formbricks/logger";
import { ZSurveyEndings } from "@formbricks/types/surveys/types";
import {
  type WorkflowApiContext,
  type WorkflowAuditDetail,
  createWorkflowsHandlers,
  createWorkflowsService,
} from "@formbricks/workflows/server";
import { getV3AuthorizationActor, getV3SessionUserId, requireV3WorkspaceAccess } from "@/app/api/v3/lib/auth";
import { problemForbidden } from "@/app/api/v3/lib/response";
import type { TV3AuditLog, TV3Authentication } from "@/app/api/v3/lib/types";
import { ENCRYPTION_KEY } from "@/lib/constants";
import { resolveSurveyActorContext } from "@/lib/survey/visibility/actor-context";
import { isSurveyOutboundAllowed, surveyOutboundVisibilitySelect } from "@/lib/survey/visibility/outbound";
import { buildHiddenSurveyWhere } from "@/lib/survey/visibility/predicate";
import { normalizeEmailForComparison } from "@/lib/utils/email";
import { getOrganizationIdFromWorkspaceId } from "@/lib/utils/helper";
import { getWorkspaceMemberEmails } from "@/lib/workspace/service";
import { getIsWorkflowsEnabled } from "@/modules/ee/license-check/lib/utils";
import { buildRecordAnalytics } from "./analytics";

/**
 * Adapter glue between the Next.js v3 routes and the framework-agnostic `@formbricks/workflows`
 * handlers. The package owns business logic, validation, serialization, and error mapping; this
 * file injects the app's concrete `prisma`/`logger` and binds an `authorize` capability to the
 * authenticated request. The real Prisma client structurally satisfies the package's narrow
 * `WorkflowsDb` port, so no cast is needed; the package never imports `@formbricks/database`.
 */
const service = createWorkflowsService({ prisma });

/** Singleton handlers; they are stateless and only close over the injected service. */
export const workflowsHandlers = createWorkflowsHandlers(service);

/**
 * Confirm a workflow trigger's referenced survey + ending cards exist in the workspace. Injected so
 * `@formbricks/workflows` stays survey-agnostic. Scoped by the survey's `(id, workspaceId)` composite
 * key; ending ids come from the survey's `endings`, parsed through `ZSurveyEndings` so the JSON
 * column is validated (not accessed untyped) before reading ids.
 */
const verifyTriggerSurvey: WorkflowApiContext["verifyTriggerSurvey"] = async ({
  workspaceId,
  surveyId,
  endingCardIds,
}) => {
  const survey = await prisma.survey.findUnique({
    where: { id_workspaceId: { id: surveyId, workspaceId } },
    select: { endings: true, ...surveyOutboundVisibilitySelect },
  });

  if (!survey) {
    return { surveyExists: false, missingEndingCardIds: [] };
  }

  const endingIds = new Set(ZSurveyEndings.parse(survey.endings).map((ending) => ending.id));
  return {
    surveyExists: true,
    // ENG-3283: a workflow forwards the survey's responses, so its survey must be workspace-visible.
    surveyNotWorkspaceVisible: !isSurveyOutboundAllowed(survey),
    missingEndingCardIds: endingCardIds.filter((endingCardId) => !endingIds.has(endingCardId)),
  };
};

/**
 * The surveys in a workspace this caller may not read (ENG-3282), so run history follows its trigger
 * survey. One indexed query over the workspace's restricted surveys — bounded by the per-workspace survey
 * limit — and none at all when nothing is hidden (marker off, an organization administrator).
 */
const buildListUnreadableSurveyIds =
  (authentication: TV3Authentication): WorkflowApiContext["listUnreadableSurveyIds"] =>
  async ({ workspaceId, organizationId, surveyIds }) => {
    const actor = getV3AuthorizationActor(authentication);
    if (!actor) throw new Error("Survey visibility resolved without an authenticated actor");

    const hidden = buildHiddenSurveyWhere(await resolveSurveyActorContext(actor, organizationId));
    if (!hidden || surveyIds?.length === 0) return [];

    const surveys = await prisma.survey.findMany({
      where: { workspaceId, ...(surveyIds ? { id: { in: surveyIds } } : {}), AND: [hidden] },
      select: { id: true },
    });
    return surveys.map((survey) => survey.id);
  };

/**
 * Bind the framework-agnostic audit sink to this request's audit log. The handlers call it once,
 * post-mutation, with the affected workflow id + workspace id + before/after snapshots; we copy
 * those onto `auditLog` (target id, old/new object) so the v3 wrapper queues a complete Enterprise
 * event.
 *
 * Organization resolution: the API-key path already set `auditLog.organizationId` from the key's
 * org (see `buildV3AuditLog`); the session path leaves it as `UNKNOWN_DATA`, so we resolve the
 * workflow's real org from `detail.workspaceId` (a first-class field — never inferred from the
 * snapshots, so snapshot reshaping or PII redaction can't silently regress it). Any failure is
 * swallowed and logged — an audit problem must never break or alter an already-successful mutation.
 */
const buildRecordAudit =
  (
    auditLog: TV3AuditLog,
    authentication: TV3Authentication,
    requestId: string
  ): NonNullable<WorkflowApiContext["recordAudit"]> =>
  async (detail: WorkflowAuditDetail) => {
    try {
      auditLog.targetId = detail.targetId;
      auditLog.oldObject = detail.oldObject;
      auditLog.newObject = detail.newObject;

      // API-key auth already carries the org; only the session path needs resolution.
      const isApiKey = !!authentication && "apiKeyId" in authentication;
      if (!isApiKey) {
        auditLog.organizationId = await getOrganizationIdFromWorkspaceId(detail.workspaceId);
      }
    } catch (error) {
      logger.withContext({ requestId }).error({ error }, "Failed to record workflow audit detail");
    }
  };

/**
 * Recipient allowlist for `send_email` actions. Injected so `@formbricks/workflows` stays
 * tenancy-agnostic: given literal recipient emails, returns the subset whose owners cannot access
 * this workspace. Enable/test use it to block a workflow from silently forwarding response data to
 * an arbitrary external inbox (ENG-2029) or to someone whose access to this workspace was revoked
 * (ENG-2186). Scoped to the workspace — not merely to its organization — so it matches both the
 * authoring picker's options and the runner's send-time backstop. Emails are compared
 * case-insensitively.
 */
const verifyRecipientsAllowed: WorkflowApiContext["verifyRecipientsAllowed"] = async ({
  workspaceId,
  emails,
}) => {
  const memberEmails = await getWorkspaceMemberEmails(workspaceId);
  const disallowedEmails = emails.filter((email) => !memberEmails.has(normalizeEmailForComparison(email)));
  return { disallowedEmails };
};

export const buildWorkflowApiContext = (
  authentication: TV3Authentication,
  requestId: string,
  instance: string,
  auditLog?: TV3AuditLog
): WorkflowApiContext => ({
  userId: getV3SessionUserId(authentication),
  requestId,
  instance,
  logger: logger.withContext({ requestId }),
  // HMAC key for redacting PII markers in audit snapshots; reuses the app's audit/encryption secret
  // so markers aren't offline-guessable. Injected as data to keep `@formbricks/workflows` agnostic.
  auditRedactionKey: ENCRYPTION_KEY,
  // Workspace access first, then the workflows entitlement (Cloud plan / self-hosted EE license)
  // for the resolved organization. Every v3 route handler and MCP tool authorizes through this
  // capability, so this is the single enforcement point for both surfaces; the returned problem
  // Response short-circuits through the package's error mapping like any authorization failure.
  authorize: async (workspaceId, access) => {
    const authorized = await requireV3WorkspaceAccess(
      authentication,
      workspaceId,
      access,
      requestId,
      instance
    );
    if (authorized instanceof Response) {
      return authorized;
    }
    const isWorkflowsEnabled = await getIsWorkflowsEnabled(authorized.organizationId);
    if (!isWorkflowsEnabled) {
      return problemForbidden(requestId, "Workflows are not enabled for this organization", instance);
    }
    return authorized;
  },
  verifyTriggerSurvey,
  verifyRecipientsAllowed,
  listUnreadableSurveyIds: buildListUnreadableSurveyIds(authentication),
  ...(auditLog ? { recordAudit: buildRecordAudit(auditLog, authentication, requestId) } : {}),
  // Product analytics (ENG-2851): always bound, unlike the audit sink, because it no-ops on its own
  // when POSTHOG_KEY is unset and there is no per-request switch to respect.
  recordAnalytics: buildRecordAnalytics(authentication, instance),
});

import { z } from "zod";
import { V3_LIST_DEFAULT_LIMIT, V3_LIST_MAX_LIMIT } from "@/app/api/v3/lib/cursor-pagination";

/**
 * Shared query schema for workspace-scoped v3 reference-list endpoints (action classes, contact
 * attribute keys): a required `workspaceId` plus the standard cursor-pagination `limit` + `cursor`.
 */
export const ZV3WorkspaceListQuery = z
  .object({
    workspaceId: z.cuid2(),
    limit: z.coerce.number().int().min(1).max(V3_LIST_MAX_LIMIT).default(V3_LIST_DEFAULT_LIMIT),
    cursor: z.string().min(1).optional(),
  })
  .strict();

export type TV3WorkspaceListQuery = z.infer<typeof ZV3WorkspaceListQuery>;

/**
 * For operations that accept no query parameters at all. `.strict()` is the point: without it an
 * unrecognized parameter is silently ignored, and a silently-ignored filter returns more data than the
 * caller believes they asked for.
 *
 * Lived in `surveys/schemas.ts` until the response operations needed it too; it was never
 * survey-specific.
 */
export const ZV3EmptyQuery = z.object({}).strict();

import { logger } from "@formbricks/logger";
import { TAuthenticationApiKey } from "@formbricks/types/auth";
import { parseApiKeyV2 } from "@/lib/crypto";
import { getApiKeyWithPermissions } from "@/modules/organization/settings/api-keys/lib/api-key";

type THeadersLike = Pick<Headers, "get">;

const BEARER_PREFIX = "bearer ";

export const getBearerTokenFromHeaders = (headers: THeadersLike): string | null => {
  const authorizationHeader = headers.get("authorization")?.trim();
  if (!authorizationHeader) {
    return null;
  }

  const lowerCasedAuthorizationHeader = authorizationHeader.toLowerCase();
  if (!lowerCasedAuthorizationHeader.startsWith(BEARER_PREFIX)) {
    return null;
  }

  const token = authorizationHeader.slice(BEARER_PREFIX.length).trim();
  return token.length > 0 ? token : null;
};
export const getApiKeyFromHeaders = (headers: THeadersLike): string | null => {
  const apiKeyHeader = headers.get("x-api-key")?.trim();
  if (apiKeyHeader) {
    return apiKeyHeader;
  }

  const bearerToken = getBearerTokenFromHeaders(headers);
  if (!bearerToken || !parseApiKeyV2(bearerToken)) {
    return null;
  }

  return bearerToken;
};

export type AuthenticateApiKeyOptions = {
  allowOrganizationOnlyApiKey?: boolean;
};

export const authenticateApiKeyFromHeaders = async (
  headers: THeadersLike,
  options: AuthenticateApiKeyOptions = {}
): Promise<TAuthenticationApiKey | null> => {
  const apiKey = getApiKeyFromHeaders(headers);
  if (!apiKey) {
    return null;
  }

  const apiKeyData = await getApiKeyWithPermissions(apiKey);
  if (!apiKeyData) {
    return null;
  }

  // ENG-1749 defense-in-depth: only honor workspace permissions whose workspace belongs to the
  // key's own organization. API keys are org-scoped, so a permission on a foreign workspace is
  // always illegitimate (it can only exist from a pre-fix bug/exploit). Filtering here — the single
  // point where the permission list is built — protects every consumer, including the read/list
  // routes that authorize off this list directly rather than through resolveBodyIdsV2.
  const apiKeyWorkspaces = apiKeyData.apiKeyWorkspaces ?? [];
  const sameOrganizationWorkspacePermissions = apiKeyWorkspaces.filter(
    (workspacePermission) => workspacePermission.workspace.organizationId === apiKeyData.organizationId
  );
  const crossOrganizationGrantCount = apiKeyWorkspaces.length - sameOrganizationWorkspacePermissions.length;

  if (crossOrganizationGrantCount > 0) {
    logger.warn(
      { component: "authorization", crossOrganizationGrantCount },
      "Cross-organization API-key workspace grants were filtered"
    );
  }

  const workspacePermissions = sameOrganizationWorkspacePermissions.map((workspacePermission) => ({
    permission: workspacePermission.permission,
    workspaceId: workspacePermission.workspaceId,
    workspaceName: workspacePermission.workspace.name,
  }));

  // Reject org-only API keys for routes that require workspace-scoped permissions
  // (those routes opt in via allowOrganizationOnlyApiKey when an org-only key is acceptable).
  // Uses the filtered list so a key left with only cross-org (now-dropped) permissions is treated
  // as having no workspace access.
  if (!options.allowOrganizationOnlyApiKey && workspacePermissions.length === 0) {
    return null;
  }

  return {
    type: "apiKey",
    workspacePermissions,
    apiKeyId: apiKeyData.id,
    organizationId: apiKeyData.organizationId,
    organizationAccess: apiKeyData.organizationAccess,
  };
};

